"""Fan-facing layout; category symbols are not product photographs."""
import re

GROUPS=[('nogizaka','乃木坂46','NOGIZAKA','#8348b3','紫に、心が動く。'),('sakurazaka','櫻坂46','SAKURAZAKA','#d95c89','桜色の、その先へ。'),('hinatazaka','日向坂46','HINATAZAKA','#249cc9','空色と、出かけよう。'),('keyakizaka','欅坂46','KEYAKIZAKA','#368963','あの頃の緑を、もう一度。'),('aobazaka','青葉坂46','AOBAZAKA','#468f8a','好きな坂道を、たどる。')]

def icon(kind):
    paths={'photo':'<rect x="9" y="5" width="28" height="36" rx="3"/><path d="M15 12h16M15 18h16M15 24h16M15 30h10"/>','stand':'<path d="M18 32V19c-6-9 2-17 6-14 6-3 13 5 6 14v13M14 33h20l5 8H9z"/><path d="M19 19h10"/>','light':'<path d="M18 29h12v13H18zM18 29l-4-19c-1-7 21-7 20 0l-4 19M20 35h8M24 1v-1M5 12H1M47 12h-4"/>'}
    return '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[kind]+'</svg>'

def redesign(out):
    for path in out.rglob('*.html'):
        if re.fullmatch(r'google[0-9a-f]+\.html',path.name): continue
        html=path.read_text()
        html=html.replace('</head>','<link rel="stylesheet" href="/fan-design.css?v=1"></head>')
        if path.name=='index.html' and path.parent==out:
            html=html.replace('<body>','<body class="fan-home">')
            hero='''<section class="fan-hero wrap" aria-label="坂道ファンのグッズと推し活ガイド"><div class="fan-hero-copy"><p class="fan-kicker"><span></span> 坂道ファンのための、グッズと推し活ガイド</p><p class="fan-group-line"><span>乃木坂46</span><span>櫻坂46</span><span>日向坂46</span></p><h1>推しのいる毎日を、<br><em>もっと、好きに。</em></h1><p class="fan-description">買い逃したあの日のグッズも、<br>大切な生写真の収納も、次のライブの準備も。</p><div class="fan-actions"><a href="#archive">過去グッズを探す <b>↗</b></a><a href="/notes.html">推し活のヒントを読む →</a></div><p class="fan-subgroups">欅坂46・青葉坂46も掲載 <span>／ 非公式ファンガイド</span></p></div><div class="fan-board"><div class="board-heading"><span>MY OSHI NOTE</span><span>好き、を集めよう。 ✧</span></div><a class="board-main" href="/notes/photo-storage.html"><div class="board-symbol">'''+icon('photo')+'''</div><div><small>COLLECTION / 01</small><strong>生写真、<br>きれいに残したい。</strong><span>スリーブ・ファイルの選び方 ↗</span></div></a><div class="board-bottom"><a href="/notes/acsta-carry.html">'''+icon('stand')+'''<small>WITH MY OSHI</small><strong>アクスタと<br>お出かけ。</strong><span>持ち運びのヒント ↗</span></a><a href="/notes/live-kit.html">'''+icon('light')+'''<small>READY FOR LIVE</small><strong>次の現場、<br>準備できた？</strong><span>参戦グッズをチェック ↗</span></a></div><p class="board-foot">集める。守る。一緒に出かける。</p></div></section>'''
            html=re.sub(r'<section class="hero wrap catalogue-intro">.*?</section>',lambda m:hero,html,count=1,flags=re.S)
            groups='<section class="fan-groups wrap" aria-label="グループ別に探す"><div class="fan-section-label"><span>CHOOSE YOUR GROUP</span><h2>あなたの坂道から。</h2></div><div class="fan-group-grid">'
            for slug,name,en,color,desc in GROUPS:
                groups+=f'<a href="/groups/{slug}.html" style="--fan-color:{color}"><small>{en}</small><strong>{name}</strong><span>{desc}</span><b aria-hidden="true">↗</b></a>'
            groups+='</div></section><section class="fan-quick wrap" aria-label="推し活メニュー"><a href="/notes/photo-sleeves.html">生写真のサイズ確認 <span>→</span></a><a href="/checklist.html">参戦持ち物チェック <span>→</span></a><a href="/notes/binoculars.html">双眼鏡の選び方 <span>→</span></a><a href="/notes/rain-kit.html">屋外ライブの雨対策 <span>→</span></a></section>'
            html=re.sub(r'<section class="group-strip wrap".*?</section>',lambda m:groups,html,count=1,flags=re.S)
            html=html.replace('買い逃した、あのグッズ。','あの日のグッズを、もう一度。')
            html=html.replace('PAST GOODS ARCHIVE','SAKAMICHI GOODS ARCHIVE')
        path.write_text(html)
    (out/'fan-design.css').write_text(CSS)

